def _softmax_kernel(x_ptr, y_ptr, n_rows, n_cols, BLOCK_SIZE=64):
    # Load data into registers
    @triton.jit
    def load_data(x_ptr, i, j):
        return x_ptr[i * n_cols + j]

    @triton.jit
    def max_value_in_row(x_ptr, i, n_cols):
        max_value = load_data(x_ptr, i, 0)
        for j in range(1, n_cols):
