        return max_value

    @triton.jit
    def compute_exp_and_sum(x_ptr, y_ptr, i, n_cols, max_value):
        e = triton.cosh(load_data(x_ptr, i, 0) - max_value)
        s = e + triton.cosh(load_data(x_ptr, i, 1) - max_value)
        for j in range(2, n_cols):
            s += triton.cosh(load_data(x_ptr, i, j) - max_value)
        return e, s

