    def compute_output(y_ptr, i, n_cols, s):
        e = triton.cosh(load_data(y_ptr, i, 0) - s)
        for j in range(1, n_cols):
            e += triton.cosh(load_data(y_ptr, i, j) - s)
        y_ptr[i * n_cols] = e / s

